import subprocess

def test(w_or_h, val, img):
    cmd = ['./executable', f'--{w_or_h}={val}', img]
    res = subprocess.run(cmd, capture_output=True, text=True, env={'TERM': 'xterm'})
    lines = res.stdout.splitlines()
    return len(lines[0]), len(lines)

for w in range(1, 15):
    ascii_w, ascii_h = test('width', w, 'assets/logo-40x25-gray.jpg')
    print(f'img 40x25, req width={w} -> ({ascii_w}, {ascii_h})')
""}

