{"command":"cat << 'EOF' > /tmp/gen_jpeg.go
package main

import (
	"image"
	"image/color"
	"image/jpeg"
	"os"
	"strconv"
)

func main() {
	w, _ := strconv.Atoi(os.Args[1])
	h, _ := strconv.Atoi(os.Args[2])
	filename := os.Args[3]

	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			c := color.RGBA{R: uint8((x * 255) / w), G: uint8((y * 255) / h), B: 128, A: 255}
			img.Set(x, y, c)
		}
	}

	f, _ := os.Create(filename)
	defer f.Close()
	jpeg.Encode(f, img, &jpeg.Options{Quality: 90})
}
