import subprocess

def get_ansi(r, g, b):
    subprocess.run(['go', 'run', '/tmp/gen_color10.go', str(r), str(g), str(b), '/tmp/c.jpg'], capture_output=True)
    res = subprocess.run(['./executable', '--colors', '--width=1', '--chars=0123456789', '/tmp/c.jpg'], capture_output=True, text=True, env={'TERM': 'xterm'})
    s = res.stdout.strip()
    if '\x1b[' in s:
        code = s.split('\x1b[')[1].split('m')[0]
        return code
    return 'none'

for g in range(100, 201, 10):
    print(f'R=200, G={g}, B=100 -> {get_ansi(200, g, 100)}')
""}

