package main

import (
	"fmt"
	"os"
	"strconv"
	"syscall"
	"unsafe"
)

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTermSize() (int, int) {
	cols := 0
	lines := 0

	if c := os.Getenv("COLUMNS"); c != "" {
		if val, err := strconv.Atoi(c); err == nil && val > 0 {
			cols = val
		}
	}
	if l := os.Getenv("LINES"); l != "" {
		if val, err := strconv.Atoi(l); err == nil && val > 0 {
			lines = val
		}
	}

	if cols == 0 || lines == 0 {
		var ws winsize
		for _, fd := range []uintptr{uintptr(syscall.Stdout), uintptr(syscall.Stdin), uintptr(syscall.Stderr)} {
			_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
			if err == 0 && ws.Col > 0 && ws.Row > 0 {
				if cols == 0 {
					cols = int(ws.Col)
				}
				if lines == 0 {
					lines = int(ws.Row)
				}
				break
			}
		}
	}

	if cols == 0 {
		cols = 80
	}
	if lines == 0 {
		lines = 24
	}

	return cols, lines
}

func main() {
	c, l := getTermSize()
	fmt.Printf("cols=%d, lines=%d\n", c, l)
}
