const versionText = `jp2a 1.0.8
Copyright 2006-2016 Christian Stigen Larsen
Distributed under the GNU General Public License (GPL) v2.
`

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

type Options struct {
	red          float64
	green        float64
	blue         float64
	chars        string
	width        int
	height       int
	termFit      bool
	termHeight   bool
	termWidth    bool
	termZoom     bool
	border       bool
	clear        bool
	colors       bool
	grayscale    bool
	fill         bool
	flipx        bool
	flipy        bool
	invert       bool
	html         bool
	htmlNoBold   bool
	htmlRaw      bool
	htmlFontsize int
	htmlTitle    string
	outputFile   string
	verbose      bool
	debug        bool
	files        []string
	hasWidth     bool
	hasHeight    bool
	hasSize      bool
}

func parseArgs() Options {
	opts := Options{
		red:          0.2989,
		green:        0.5866,
		blue:         0.1145,
		chars:        "   ...',;:clodxkO0KXNWM",
		htmlFontsize: 8,
		htmlTitle:    "jp2a converted image",
	}

	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-" {
			opts.files = append(opts.files, "-")
			continue
		}
		if !strings.HasPrefix(arg, "-") {
			opts.files = append(opts.files, arg)
			continue
		}

		if strings.HasPrefix(arg, "--red=") {
			v, err := strconv.ParseFloat(arg[6:], 64)
			if err != nil {
				unknownOption(arg)
			}
			opts.red = v
		} else if strings.HasPrefix(arg, "--green=") {
			v, err := strconv.ParseFloat(arg[8:], 64)
			if err != nil {
				unknownOption(arg)
			}
			opts.green = v
		} else if strings.HasPrefix(arg, "--blue=") {
			v, err := strconv.ParseFloat(arg[7:], 64)
			if err != nil {
				unknownOption(arg)
			}
			opts.blue = v
		} else if strings.HasPrefix(arg, "--chars=") {
			opts.chars = arg[8:]
		} else if strings.HasPrefix(arg, "--width=") {
			v, err := strconv.Atoi(arg[8:])
			if err != nil || v < 1 {
				unknownOption(arg)
			}
			opts.width = v
			opts.hasWidth = true
		} else if strings.HasPrefix(arg, "--height=") {
			v, err := strconv.Atoi(arg[9:])
			if err != nil || v < 1 {
				unknownOption(arg)
			}
			opts.height = v
			opts.hasHeight = true
		} else if strings.HasPrefix(arg, "--size=") {
			parts := strings.Split(arg[7:], "x")
			if len(parts) != 2 {
				unknownOption(arg)
			}
			w, err1 := strconv.Atoi(parts[0])
			h, err2 := strconv.Atoi(parts[1])
			if err1 != nil || err2 != nil || w < 1 || h < 1 {
				unknownOption(arg)
			}
			opts.width = w
			opts.height = h
			opts.hasSize = true
		} else if strings.HasPrefix(arg, "--html-fontsize=") {
			v, err := strconv.Atoi(arg[16:])
			if err != nil || v < 1 {
				unknownOption(arg)
			}
			opts.htmlFontsize = v
		} else if strings.HasPrefix(arg, "--html-title=") {
			opts.htmlTitle = arg[13:]
		} else if strings.HasPrefix(arg, "--output=") {
			opts.outputFile = arg[9:]
		} else if strings.HasPrefix(arg, "--background=") {
			val := arg[13:]
			if val == "light" {
				opts.invert = true
			} else if val == "dark" {
				opts.invert = false
			} else {
				unknownOption(arg)
			}
		} else if arg == "-b" || arg == "--border" {
			opts.border = true
		} else if arg == "-clear" || arg == "--clear" {
			opts.clear = true
		} else if arg == "--colors" {
			opts.colors = true
		} else if arg == "-d" || arg == "--debug" {
			opts.debug = true
		} else if arg == "--fill" || arg == "--html-fill" {
			opts.fill = true
		} else if arg == "-x" || arg == "--flipx" {
			opts.flipx = true
		} else if arg == "-y" || arg == "--flipy" {
			opts.flipy = true
		} else if arg == "-f" || arg == "--term-fit" {
			opts.termFit = true
		} else if arg == "--term-height" {
			opts.termHeight = true
		} else if arg == "--term-width" {
			opts.termWidth = true
		} else if arg == "-z" || arg == "--term-zoom" || arg == "--zoom" {
			opts.termZoom = true
		} else if arg == "--grayscale" {
			opts.grayscale = true
		} else if arg == "-h" || arg == "--help" {
			fmt.Fprintln(os.Stderr, helpText)
			os.Exit(0)
		} else if arg == "--html" {
			opts.html = true
		} else if arg == "--html-no-bold" {
			opts.htmlNoBold = true
		} else if arg == "--html-raw" {
			opts.htmlRaw = true
		} else if arg == "-i" || arg == "--invert" {
			opts.invert = !opts.invert
		} else if arg == "-v" || arg == "--verbose" {
			opts.verbose = true
		} else if arg == "-V" || arg == "--version" {
			fmt.Fprint(os.Stderr, versionText)
			os.Exit(0)
		} else {
			unknownOption(arg)
		}
	}

	return opts
}

func unknownOption(opt string) {
	fmt.Fprintf(os.Stderr, "Unknown option %s\n\n%s\n", opt, helpText)
	os.Exit(1)
}

func getTermDimensions() (int, int) {
	term := os.Getenv("TERM")
	if term == "" {
		fmt.Fprintln(os.Stderr, "Environment variable TERM not set.")
		os.Exit(1)
	}

	if len(term) > 0 {
		c := string(term[0])
		paths := []string{
			"/lib/terminfo/" + c + "/" + term,
			"/usr/share/terminfo/" + c + "/" + term,
			"/etc/terminfo/" + c + "/" + term,
		}
		found := false
		for _, p := range paths {
			if _, err := os.Stat(p); err == nil {
				found = true
				break
			}
		}
		if !found {
			fmt.Fprintf(os.Stderr, "Terminal type '%s' not recognized.\n", term)
			os.Exit(1)
		}
	}

	cols := 0
	lines := 0

	if c := os.Getenv("COLUMNS"); c != "" {
		if val, err := strconv.Atoi(c); err == nil && val > 0 {
			cols = val
		}
	}
	if l := os.Getenv("LINES"); l != "" {
		if val, err := strconv.Atoi(l); err == nil && val > 0 {
			lines = val
		}
	}

	if cols == 0 || lines == 0 {
		var ws winsize
		for _, fd := range []uintptr{uintptr(syscall.Stdout), uintptr(syscall.Stdin), uintptr(syscall.Stderr)} {
			_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
			if err == 0 && ws.Col > 0 && ws.Row > 0 {
				if cols == 0 {
					cols = int(ws.Col)
				}
				if lines == 0 {
					lines = int(ws.Row)
				}
				break
			}
		}
	}

	if cols == 0 {
		cols = 80
	}
	if lines == 0 {
		lines = 24
	}

	return cols, lines
}

func getAnsiColor(r, g, b uint8) string {
	maxV := r
	if g > maxV {
		maxV = g
	}
	if b > maxV {
		maxV = b
	}

	if maxV < 30 {
		return ""
	}

	rFlag := (uint32(r)*8 >= uint32(maxV)*7)
	gFlag := (uint32(g)*8 >= uint32(maxV)*7)
	bFlag := (uint32(b)*8 >= uint32(maxV)*7)

	code := 30
	if rFlag {
		code += 1
	}
	if gFlag {
		code += 2
	}
	if bFlag {
		code += 4
	}

	if code == 30 || code == 37 {
		return ""
	}
	return strconv.Itoa(code)
}

func processFile(filename string, opts Options, outWriter io.Writer) error {
	var r io.Reader
	if filename == "-" {
		r = os.Stdin
	} else if strings.HasPrefix(filename, "http://") || strings.HasPrefix(filename, "https://") || strings.HasPrefix(filename, "ftp://") || strings.HasPrefix(filename, "ftps://") || strings.HasPrefix(filename, "file://") || strings.HasPrefix(filename, "tftp://") {
		if strings.HasPrefix(filename, "file://") {
			path := strings.TrimPrefix(filename, "file://")
			f, err := os.Open(path)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Can't open %s\n", filename)
				return err
			}
			defer f.Close()
			r = f
		} else {
			resp, err := http.Get(filename)
			if err != nil {
				fmt.Fprintln(os.Stderr, "Empty input file")
				return err
			}
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				fmt.Fprintln(os.Stderr, "Empty input file")
				return fmt.Errorf("http error %d", resp.StatusCode)
			}
			r = resp.Body
		}
	} else {
		f, err := os.Open(filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Can't open %s\n", filename)
			return err
		}
		defer f.Close()
		r = f
	}

	data, err := io.ReadAll(r)
	if err != nil || len(data) == 0 {
		fmt.Fprintln(os.Stderr, "Empty input file")
		return fmt.Errorf("empty input")
	}

	if len(data) == 1 {
		fmt.Fprintf(os.Stderr, "Premature end of JPEG file\nNot a JPEG file: starts with 0x%02x 0xff\n", data[0])
		return fmt.Errorf("invalid jpeg")
	}

	if data[0] != 0xff || data[1] != 0xd8 {
		fmt.Fprintf(os.Stderr, "Not a JPEG file: starts with 0x%02x 0x%02x\n", data[0], data[1])
		return fmt.Errorf("not jpeg")
	}

	img, err := jpeg.Decode(bytes.NewReader(data))
	if err != nil {
		fmt.Fprintln(os.Stderr, "Premature end of JPEG file")
		return err
	}

	bounds := img.Bounds()
	imgW := bounds.Dx()
	imgH := bounds.Dy()

	var termCols, termLines int
	needTerm := !opts.hasWidth && !opts.hasHeight && !opts.hasSize
	if needTerm || opts.termFit || opts.termHeight || opts.termWidth || opts.termZoom {
		termCols, termLines = getTermDimensions()
	}

	var outW, outH int

	if opts.hasWidth && opts.hasHeight {
		outW = opts.width
		outH = opts.height
	} else if opts.hasWidth {
		outW = opts.width
		outH = int(math.Round(float64(outW) * float64(imgH) / float64(imgW) * 0.5))
		if outH < 1 {
			outH = 1
		}
	} else if opts.hasHeight {
		outH = opts.height
		outW = int(math.Round(float64(outH) * float64(imgW) / float64(imgH) * 2.0))
		if outW < 1 {
			outW = 1
		}
	} else if opts.termZoom {
		maxW := termCols
		maxH := termLines - 1
		if opts.border {
			maxW -= 2
			maxH -= 2
		}
		if maxW < 1 {
			maxW = 1
		}
		if maxH < 1 {
			maxH = 1
		}
		outW = maxW
		outH = maxH
	} else if opts.termWidth {
		maxW := termCols
		if opts.border {
			maxW -= 2
		}
		if maxW < 1 {
			maxW = 1
		}
		outW = maxW
		outH = int(math.Round(float64(outW) * float64(imgH) / float64(imgW) * 0.5))
		if outH < 1 {
			outH = 1
		}
	} else if opts.termHeight {
		maxH := termLines - 1
		if opts.border {
			maxH -= 2
		}
		if maxH < 1 {
			maxH = 1
		}
		outH = maxH
		outW = int(math.Round(float64(outH) * float64(imgW) / float64(imgH) * 2.0))
		if outW < 1 {
			outW = 1
		}
	} else { // default or termFit
		maxW := termCols
		maxH := termLines - 1
		if opts.border {
			maxW -= 2
			maxH -= 2
		}
		if maxW < 1 {
			maxW = 1
		}
		if maxH < 1 {
			maxH = 1
		}

		outW = int(math.Round(float64(maxH) * float64(imgW) / float64(imgH) * 2.0))
		if outW <= maxW {
			outH = maxH
		} else {
			outW = maxW
			outH = int(math.Round(float64(outW) * float64(imgH) / float64(imgW) * 0.5))
		}
		if outW < 1 {
			outW = 1
		}
		if outH < 1 {
			outH = 1
		}
	}

	if opts.verbose {
		if filename != "-" {
			fmt.Fprintf(os.Stderr, "File: %s\n", filename)
		}
		fmt.Fprintf(os.Stderr, "Source width: %d\n", imgW)
		fmt.Fprintf(os.Stderr, "Source height: %d\n", imgH)
		fmt.Fprintf(os.Stderr, "Source color components: 1\n")
		fmt.Fprintf(os.Stderr, "Output width: %d\n", outW)
		fmt.Fprintf(os.Stderr, "Output height: %d\n", outH)
		fmt.Fprintf(os.Stderr, "Output palette (%d chars): '%s'\n", len(opts.chars), opts.chars)

		hashes := []int{4, 6, 9, 11, 13, 15, 17, 19, 22, 24, 26, 28, 30, 32, 35, 37, 39, 41, 43, 45, 48, 50, 52, 54, 56}
		for _, h := range hashes {
			dots := 56 - h
			fmt.Fprintf(os.Stderr, "Decompressing image [%s%s]\n", strings.Repeat("#", h), strings.Repeat(".", dots))
		}
	}

	if opts.clear {
		fmt.Fprint(outWriter, "\x1b[2J\x1b[0;0H")
	}

	if opts.html {
		if !opts.htmlRaw {
			bgColor := "black"
			if opts.invert {
				bgColor = "white"
			}
			fontWeight := "bold"
			if opts.htmlNoBold {
				fontWeight = "normal"
			}
			colorLine := ""
			if !opts.colors {
				if opts.invert {
					colorLine = "\n   color: black;"
				} else {
					colorLine = "\n   color: white;"
				}
			}

			fmt.Fprintf(outWriter, "<?xml version='1.0' encoding='ISO-8859-1'?>\n")
			fmt.Fprintf(outWriter, "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n")
			fmt.Fprintf(outWriter, "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n<head>\n<title>%s</title>\n", opts.htmlTitle)
			fmt.Fprintf(outWriter, "<style type='text/css'>\nbody {\nbackground-color: %s;\n}\n.ascii {\n   font-family: Courier;%s\n   font-size:%dpt;\n   font-weight: %s;\n}\n</style>\n</head>\n<body>\n<div class='ascii'><pre>\n", bgColor, colorLine, opts.htmlFontsize, fontWeight)
		}
	}

	if opts.border {
		borderTop := "+" + strings.Repeat("-", outW) + "+"
		if opts.html {
			fmt.Fprintf(outWriter, "%s<br/>\n", borderTop)
		} else {
			fmt.Fprintf(outWriter, "%s\n", borderTop)
		}
	}

	paletteLen := len(opts.chars)

	for y := 0; y < outH; y++ {
		sy := y
		if opts.flipy {
			sy = outH - 1 - y
		}
		iy := (sy * imgH) / outH

		if opts.border {
			fmt.Fprint(outWriter, "|")
		}

		for x := 0; x < outW; x++ {
			sx := x
			if opts.flipx {
				sx = outW - 1 - x
			}
			ix := (sx * imgW) / outW

			r, g, b, _ := img.At(bounds.Min.X+ix, bounds.Min.Y+iy).RGBA()
			r8 := uint8(r >> 8)
			g8 := uint8(g >> 8)
			b8 := uint8(b >> 8)

			lum := opts.red*float64(r8) + opts.green*float64(g8) + opts.blue*float64(b8)
			if lum < 0 {
				lum = 0
			}
			if lum > 255 {
				lum = 255
			}

			idx := int((lum / 255.0) * float64(paletteLen-1) + 0.5)
			if idx < 0 {
				idx = 0
			}
			if idx >= paletteLen {
				idx = paletteLen - 1
			}

			if opts.invert {
				idx = (paletteLen - 1) - idx
			}

			ch := opts.chars[idx : idx+1]

			if opts.html {
				if opts.colors {
					var hexColor string
					if opts.grayscale {
						gVal := uint8(math.Round(lum))
						hexColor = fmt.Sprintf("#%02x%02x%02x", gVal, gVal, gVal)
					} else {
						hexColor = fmt.Sprintf("#%02x%02x%02x", r8, g8, b8)
					}

					chHtml := ch
					if ch == " " && opts.colors {
						chHtml = "&nbsp;"
					}

					if opts.fill {
						fgR := uint8(math.Round(float64(r8) * opts.red))
						fgG := uint8(math.Round(float64(g8) * opts.green))
						fgB := uint8(math.Round(float64(b8) * opts.blue))
						fgHex := fmt.Sprintf("#%02x%02x%02x", fgR, fgG, fgB)
						fmt.Fprintf(outWriter, "<span style='color:%s; background-color:%s;'>%s</span>", fgHex, hexColor, chHtml)
					} else {
						fmt.Fprintf(outWriter, "<span style='color:%s;'>%s</span>", hexColor, chHtml)
					}
				} else {
					fmt.Fprint(outWriter, ch)
				}
			} else { // plain text / ANSI
				if opts.colors {
					var cCode string
					if opts.grayscale {
						gVal := uint8(math.Round(lum))
						cCode = getAnsiColor(gVal, gVal, gVal)
					} else {
						cCode = getAnsiColor(r8, g8, b8)
					}

					if cCode != "" {
						fmt.Fprintf(outWriter, "\x1b[%sm%s\x1b[0m", cCode, ch)
					} else {
						fmt.Fprint(outWriter, ch)
					}
				} else {
					fmt.Fprint(outWriter, ch)
				}
			}
		}

		if opts.border {
			fmt.Fprint(outWriter, "|")
		}

		if opts.html {
			fmt.Fprint(outWriter, "<br/>\n")
		} else {
			fmt.Fprint(outWriter, "\n")
		}
	}

	if opts.border {
		borderBottom := "+" + strings.Repeat("-", outW) + "+"
		if opts.html {
			fmt.Fprintf(outWriter, "%s<br/>\n", borderBottom)
		} else {
			fmt.Fprintf(outWriter, "%s\n", borderBottom)
		}
	}

	if opts.html && !opts.htmlRaw {
		fmt.Fprint(outWriter, "</pre>\n</div>\n</body>\n</html>\n")
	}

	return nil
}

func main() {
	opts := parseArgs()

	if math.Abs((opts.red+opts.green+opts.blue)-1.0) > 0.001 {
		fmt.Fprintln(os.Stderr, "Weights RED + GREEN + BLUE must equal 1.0")
		os.Exit(1)
	}

	if len(opts.chars) < 2 {
		fmt.Fprintln(os.Stderr, "You must specify at least two characters in --chars.")
		os.Exit(1)
	}

	if len(opts.files) == 0 {
		fmt.Fprintln(os.Stderr, "No files specified.\n")
		fmt.Fprintln(os.Stderr, helpText)
		os.Exit(1)
	}

	var outWriter io.Writer = os.Stdout
	if opts.outputFile != "" && opts.outputFile != "-" {
		f, err := os.Create(opts.outputFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not open '%s' for writing.\n", opts.outputFile)
			os.Exit(1)
		}
		defer f.Close()
		outWriter = f
	}

	for _, file := range opts.files {
		err := processFile(file, opts, outWriter)
		if err != nil {
			os.Exit(1)
		}
	}
}
EOF
go build -o executable main.go"}

